package com.asmj.marketplace.advertising;
import java.time.Instant; import org.springframework.data.annotation.Id; import org.springframework.data.mongodb.core.mapping.Document; import org.springframework.data.mongodb.core.index.Indexed;
@Document("advertisement_placements") public class AdPlacement { @Id private String id; @Indexed(unique=true) private String code; private String name; private String description; private String desktopSize; private String mobileSize; private int maxConcurrent=3; private boolean enabled=true; private Instant updatedAt=Instant.now();
public String getId(){return id;} public void setId(String v){id=v;} public String getCode(){return code;} public void setCode(String v){code=v;} public String getName(){return name;} public void setName(String v){name=v;} public String getDescription(){return description;} public void setDescription(String v){description=v;} public String getDesktopSize(){return desktopSize;} public void setDesktopSize(String v){desktopSize=v;} public String getMobileSize(){return mobileSize;} public void setMobileSize(String v){mobileSize=v;} public int getMaxConcurrent(){return maxConcurrent;} public void setMaxConcurrent(int v){maxConcurrent=v;} public boolean isEnabled(){return enabled;} public void setEnabled(boolean v){enabled=v;} public Instant getUpdatedAt(){return updatedAt;} public void setUpdatedAt(Instant v){updatedAt=v;} }
